script = json.loads((ROOT / "episodes/ep_1/01_剧本/script_contract_ep_1.json").read_text(encoding="utf-8"))
plan = json.loads((ROOT / "00_制作控制/drama_plan.json").read_text(encoding="utf-8"))
LINES = {line["line_id"]: (scene["scene_id"], line) for scene in script["scenes"] for line in scene["speech_lines"]}
SCENE_NAMES = {"E01S01":"角楼立规", "E01S02":"夜访问恩", "E01S03":"松亭赎狐", "E01S04":"认亲赠环", "E01S05":"十余年日常", "E01S06":"婚宴备器", "E01S07":"急难相助", "E01S08":"五更辞别", "E01S09":"次日休致", "E01S10":"晚年调息", "E01S11":"四色终镜"}
