segments = []
def seg(scene, title, profile, rationale, takeaway, hook, shots, tail="cuttable_completion", exception="", tail_reason=""):
    segments.append(dict(scene=scene,title=title,profile=profile,rationale=rationale,takeaway=takeaway,hook=hook,shots=shots,tail=tail,exception=exception,tail_reason=tail_reason))
def sh(dur,size,view,move,angle,duty,action,change,lines=(),sfx="夜风低鸣",cutin="动作承接",cutout="反应切",cont="沿用固定轴线、光位和人物朝向",perf=("维持礼数","隐藏真实压力","目光与手部出现可见变化","对方视线被动作吸引")):
    return dict(duration=dur,size=size,view=view,move=move,angle=angle,duty=duty,action=action,change=change,lines=list(lines),sfx=sfx,cutin=cutin,cutout=cutout,cont=cont,perf=perf)

